package pe.edu.upeu.pago.client;
import java.util.List; import java.math.BigDecimal; import pe.edu.upeu.pago.dto.*; import org.springframework.cloud.openfeign.FeignClient; import org.springframework.web.bind.annotation.*;
@FeignClient(name="kido-inscripcion-ms",fallbackFactory=InscripcionFeignFallbackFactory.class)
public interface InscripcionFeignClient { @PostMapping("/internal/v1/inscripciones/compra") InscripcionDto crearCompra(@RequestBody CrearCompraRequest request); @GetMapping("/internal/v1/inscripciones/por-estudiante-curso") InscripcionDto buscar(@RequestParam("estudianteId") Long estudianteId,@RequestParam("cursoId") Long cursoId); @PutMapping("/internal/v1/inscripciones/por-estudiante-curso/revocar") InscripcionDto revocar(@RequestParam("estudianteId") Long estudianteId,@RequestParam("cursoId") Long cursoId); @GetMapping("/internal/v1/inscripciones/{id}/certificado") CertificadoInscripcionDto certificado(@PathVariable("id") Long id); @PutMapping("/internal/v1/inscripciones/{id}/certificado/confirmar-pago") CertificadoInscripcionDto confirmarPagoCertificado(@PathVariable("id") Long id); record CrearCompraRequest(Long estudianteId,Long cursoId,List<Long> leccionIds,Integer progresoMinimo,Integer asistenciaMinima,Boolean certificadoHabilitado,BigDecimal certificadoCosto){} }
